+        let r = (x_tip + p[0]).hypot(p[1]);
+        let reach = c.over(p[2], p[2]).expect("a facet point has a band");
+        let (lo, hi) = reach.radii(x_tip);
+        assert!(lo <= r + 1e-9 && r <= hi + 1e-9, "point {p:?} tip {x_tip}: r {r} outside [{lo}, {hi}]");
+    }
